UPDATE router_explicit_cache
SET status = 'FAILED',
    updated_at = CURRENT_TIMESTAMP(3)
WHERE cache_id = #{cacheId}
AND api_key_id = #{apiKeyId}
AND status = 'CREATING'

UPDATE router_explicit_cache
SET status = 'UNKNOWN',
    updated_at = CURRENT_TIMESTAMP(3)
WHERE cache_id = #{cacheId}
AND api_key_id = #{apiKeyId}
AND status = 'CREATING'
